194: function tickWalk(dt) {
195:   const p = playerPosition();
196:   if (movementStick.active) {
197:     const length = Math.hypot(movementStick.x, movementStick.y) || 1;
198:     const speed = 0.14 * dt;
199:     const bounds = walkBounds[game.place] || { minY: 20, maxY: 350 };
200:     p.x = Math.max(0, Math.min(W, p.x + movementStick.x / length * speed));
201:     p.y = Math.max(bounds.minY, Math.min(bounds.maxY, p.y + movementStick.y / length * speed));
202:     p.walking = true;
203:     if (movementStick.x) p.face = movementStick.x < 0 ? -1 : 1;
204:     if (tryEnterWorldRoute()) return;
205:     return;
206:   }
207:   if (p.tx == null) { p.walking = false; return; }
208:   const dx = p.tx - p.x, dy = p.ty - p.y;
209:   const d = Math.hypot(dx, dy);
210:   const step = Math.min(0.18 * dt, d);
211:   if (d < 1.5) {
212:     p.x = p.tx; p.y = p.ty;
213:     delete p.tx; delete p.ty;
214:     p.walking = false;
215:     if (tryEnterWorldRoute()) return;
216:     if (p.auto) { delete p.auto; interact(); }
217:     save();
218:     return;
219:   }
220:   p.x += dx / d * step;
221:   p.y += dy / d * step;
222:   p.walking = true;
223:   if (Math.abs(dx) > 1) p.face = dx < 0 ? -1 : 1;
224:   tryEnterWorldRoute();
225: }
