const fs = require('node:fs');
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
  const page = targets.find(target => target.type === 'page');
  if (!page) throw new Error('No Chrome page target');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
  let id = 0;
  const pending = new Map();
  ws.onmessage = event => {
    const message = JSON.parse(event.data);
    if (message.id && pending.has(message.id)) {
      const { resolve, reject } = pending.get(message.id);
      pending.delete(message.id);
      message.error ? reject(new Error(message.error.message)) : resolve(message.result);
    }
  };
  const send = (method, params = {}) => new Promise((resolve, reject) => {
    const requestId = ++id;
    pending.set(requestId, { resolve, reject });
    ws.send(JSON.stringify({ id: requestId, method, params }));
  });
  const evaluate = async expression => {
    const result = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (result.exceptionDetails) throw new Error(result.exceptionDetails.text);
    return result.result.value;
  };
  const mouse = (type, x, y, button = 'left', buttons = type === 'mouseReleased' ? 0 : 1) => send('Input.dispatchMouseEvent', { type, x, y, button, buttons, clickCount: 1 });
  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 960, deviceScaleFactor: 1, mobile: false });
  await send('Page.navigate', { url: 'http://127.0.0.1:3000/' });
  let ready = false;
  for (let i = 0; i < 50; i++) {
    await wait(100);
    try { ready = await evaluate("!!document.querySelector('.joystick') && !!window.gameLoopReady"); } catch {}
    if (ready) break;
    try { ready = await evaluate("!!document.querySelector('.joystick') && typeof game !== 'undefined'"); } catch {}
    if (ready) break;
  }
  if (!ready) throw new Error('Game or joystick failed to initialize');
  const initial = await evaluate("({ place: game.place, x: game.player[game.place].x, y: game.player[game.place].y, controls: document.querySelectorAll('.joystick-tip').length })");
  const stick = await evaluate("(()=>{const r=document.querySelector('.joystick').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,travel:r.width*.32}})()");
  await mouse('mouseMoved', stick.x, stick.y, 'none', 0);
  await mouse('mousePressed', stick.x, stick.y);
  await mouse('mouseMoved', stick.x + stick.travel * 0.48, stick.y, 'none', 1);
  await wait(900);
  await mouse('mouseReleased', stick.x + stick.travel * 0.48, stick.y);
  await wait(150);
  const moved = await evaluate("({ place: game.place, x: game.player[game.place].x, y: game.player[game.place].y, stickActive: document.querySelector('.joystick').classList.contains('is-active') })");
  if (moved.x <= initial.x + 5 || moved.place !== initial.place || moved.stickActive) throw new Error(`Joystick movement/release failed: ${JSON.stringify({initial,moved})}`);
  await evaluate("(()=>{const p=game.player.cabin;p.x=426;p.y=326})()");
  await evaluate("document.querySelector('.walk-use').click()");
  await wait(120);
  const interact = await evaluate("({toast:document.querySelector('#toast').textContent.trim(), catHearts:game.cats[game.cat].hearts, modal:!!document.querySelector('#modalRoot').innerHTML})");
  if (!interact.toast && !interact.modal && interact.catHearts === 0) throw new Error(`Interact button did not trigger an action: ${JSON.stringify(interact)}`);
  await evaluate("(()=>{const p=game.player.cabin;p.x=635;p.y=340})()");
  const routeStick = await evaluate("(()=>{const r=document.querySelector('.joystick').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2,travel:r.width*.32}})()");
  await mouse('mouseMoved', routeStick.x, routeStick.y, 'none', 0);
  await mouse('mousePressed', routeStick.x, routeStick.y);
  await mouse('mouseMoved', routeStick.x + routeStick.travel, routeStick.y, 'none', 1);
  await wait(250);
  await mouse('mouseReleased', routeStick.x + routeStick.travel, routeStick.y);
  await wait(150);
  const route = await evaluate("({place:game.place,title:document.querySelector('#sceneTitle').textContent.trim()})");
  if (route.place !== 'garden') throw new Error(`Joystick route transition failed: ${JSON.stringify(route)}`);
  await evaluate("go('cabin')");
  await wait(300);
  const shot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 82, captureBeyondViewport: false });
  fs.writeFileSync('/tmp/opencode/mosswood-latest.jpg', Buffer.from(shot.data, 'base64'));
  const screenshotInfo = await evaluate("({width:innerWidth,height:innerHeight,joystick:!!document.querySelector('.joystick'),interact:!!document.querySelector('.walk-use'),tipCount:document.querySelectorAll('.joystick-tip').length,scrollHeight:document.documentElement.scrollHeight})");
  console.log(JSON.stringify({ initial, moved, interact, route, screenshotInfo, screenshot: '/tmp/opencode/mosswood-latest.jpg' }, null, 2));
  ws.close();
})().catch(error => { console.error(error); process.exit(1); });

