155: function go(place) {
156:   if (!locations[place]) return;
157:   game.place = place;
158:   game.visited = game.visited || {};
159:   game.visited[place] = true;
160:   if (Object.keys(game.visited).length >= 3) announceAchievement('wanderer', 'Little Wanderer', 'Visited three places');
161:   save();
162: }

